INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenbanken > Datenquellen > Sensoren
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Sensoren als Datenquellen kontinuierlich Echtzeitdaten liefern?', 2, '[{"text": "Ja", "correct": true, "because": "Sensoren erfassen Daten oft in Echtzeit"}, {"text": "Nein", "correct": false, "because": "Kontinuierliche Erfassung ist typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Sensordaten immer numerisch, wie z. B. Temperatur oder Druck?', 2, '[{"text": "Nein", "correct": true, "because": "Sensoren können auch Zustände oder Bilder liefern"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich numerisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Sensordaten vor der Speicherung in einer Datenbank immer verarbeitet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Rohdaten können direkt gespeichert werden"}, {"text": "Ja", "correct": false, "because": "Verarbeitung ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Sensoren als Datenquellen auch Fehler oder ungenaue Daten liefern?', 2, '[{"text": "Ja", "correct": true, "because": "Sensoren können durch Störungen ungenau sein"}, {"text": "Nein", "correct": false, "because": "Fehler sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Sensordaten in Datenbanken immer mit einem Zeitstempel versehen?', 2, '[{"text": "Nein", "correct": true, "because": "Zeitstempel sind üblich, aber nicht zwingend"}, {"text": "Ja", "correct": false, "because": "Abhängig vom System"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Art von Daten liefern Sensoren am häufigsten?', 2, '[{"text": "Numerische Werte", "correct": true, "because": "Temperatur, Druck etc. sind typisch"}, {"text": "Textdaten", "correct": false, "because": "Weniger üblich"}, {"text": "Bilddaten", "correct": false, "because": "Spezifische Sensoren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Datentyp wird typischerweise verwendet, um Sensordaten wie Temperaturwerte in einer Datenbank zu speichern?', 3, '[{"text": "Gleitkomma", "correct": true, "because": "Geeignet für Dezimalwerte wie Temperatur"}, {"text": "Text", "correct": false, "because": "Ineffizient für Zahlen"}, {"text": "Boolesch", "correct": false, "because": "Für binäre Werte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft von Sensordaten ist für die Analyse oft entscheidend?', 2, '[{"text": "Zeitstempel", "correct": true, "because": "Zeitliche Abfolge ist wichtig"}, {"text": "Textlänge", "correct": false, "because": "Irrelevant"}, {"text": "Dateigröße", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderung tritt bei Sensordaten als Datenquelle häufig auf?', 2, '[{"text": "Datenqualität", "correct": true, "because": "Ungenauigkeiten durch Störungen"}, {"text": "Datenlöschung", "correct": false, "because": "Weniger häufig"}, {"text": "Datenformatierung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenbankfunktion ist für die Verarbeitung von Sensordaten besonders nützlich?', 2, '[{"text": "Zeitreihenunterstützung", "correct": true, "because": "Optimiert für Echtzeitdaten"}, {"text": "Textsuche", "correct": false, "because": "Weniger relevant"}, {"text": "BLOB-Speicherung", "correct": false, "because": "Für binäre Daten"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Daten können Sensoren als Datenquellen liefern?', 4, '[{"text": "Numerische Werte", "correct": true, "because": "Temperatur, Druck etc."}, {"text": "Boolesche Werte", "correct": true, "because": "Ein/Aus-Zustände"}, {"text": "Bilddaten", "correct": true, "because": "Von Bildsensoren"}, {"text": "Statische Texte", "correct": false, "because": "Weniger typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Sensordaten für Datenbanken relevant?', 3, '[{"text": "Echtzeitfähigkeit", "correct": true, "because": "Kontinuierliche Erfassung"}, {"text": "Zeitliche Reihenfolge", "correct": true, "because": "Analyse von Verläufen"}, {"text": "Hohe Datenrate", "correct": true, "because": "Viele Datenpunkte"}, {"text": "Statische Werte", "correct": false, "because": "Dynamisch typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen treten bei der Speicherung von Sensordaten auf?', 4, '[{"text": "Datenvolumen", "correct": true, "because": "Hohe Datenmengen"}, {"text": "Datenqualität", "correct": true, "because": "Ungenauigkeiten möglich"}, {"text": "Echtzeitverarbeitung", "correct": true, "because": "Schnelle Speicherung nötig"}, {"text": "Textlänge", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datentypen sind für Sensordaten in Datenbanken geeignet?', 3, '[{"text": "Gleitkomma", "correct": true, "because": "Für Messwerte"}, {"text": "Datumswert", "correct": true, "because": "Für Zeitstempel"}, {"text": "BLOB", "correct": true, "because": "Für Bilddaten"}, {"text": "Fester Text", "correct": false, "because": "Weniger effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Sensoren als Datenquellen?', 3, '[{"text": "Kontinuierliche Datenerfassung", "correct": true, "because": "Echtzeitdaten"}, {"text": "Automatisierung", "correct": true, "because": "Keine manuelle Eingabe"}, {"text": "Vielfalt der Daten", "correct": true, "because": "Verschiedene Typen"}, {"text": "Langsame Verarbeitung", "correct": false, "because": "Kein Vorteil"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Sensoren liefern oft Echtzeitdaten. b) Sie erfassen nur numerische Werte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Echtzeit ja, nicht nur numerisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sensordaten können ungenau sein. b) Sie müssen immer verarbeitet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ungenauigkeit ja, Verarbeitung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zeitstempel sind bei Sensordaten üblich. b) Sensoren liefern ausschließlich Bilddaten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeitstempel ja, Bilddaten nicht exklusiv"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Sensordaten erfordern oft hohe Speicherkapazität. b) Sie sind immer fehlerfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kapazität ja, Fehler möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Gleitkommawerte sind für Sensormessungen geeignet. b) Sensoren liefern keine Echtzeitdaten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gleitkomma ja, Echtzeit typisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

